(a) Let $\mathcal{S}_a =\{u_0, u_1, \ldots, u_m\}$ where $u_0=a$.
For $j=1,\ldots, m$, let $\tau_j$ be the minimum PST time from $a$ to $u_j$, and let $\tau_0=0$.  Without loss of generality, we assume 
\begin{equation*}
    \tau_0<\tau_1 < \cdots < \tau_m.
\end{equation*}  
Note that $\tau_m$ is less than the minimum period of $a$.                        

For $j=1,\ldots,m$, PST from $u_{j-1}$ to $u_j$ occurs at time $(\tau_j-\tau_{j-1})$, hence 
\begin{equation*}
    U\left(\tau_j-\tau_{j-1}\right) = \lambda_j P_j,
\end{equation*}
for some fixed-point-free permutation matrix $P_j \in \mathcal{A}$ satisfying 
$P_ju_{j-1}=u_j$ and phase $\lambda_j$.

Suppose there exists $k<m$ such that $\tau_1=\tau_j-\tau_{j-1}$,
for $j=1,\ldots,k$, and $\tau_1\neq \tau_{k+1}-\tau_k$.
Then $P_1=\cdots=P_k$ and $P_{k+1}$ are distinct permutation matrices in $\mathcal{A}$ and $P_1 u_j \neq P_{k+1}u_j$, for $j=0,\ldots,m$.

If $\tau_{k+1}-\tau_k<\tau_1$ then 
\begin{equation*}
    U(\tau_{k+1}-\tau_k) a = \lambda_{k+1}P_{k+1}a.
\end{equation*}
So PST occurs from $a$ to $P_{k+1}a$ at time strictly less than $\tau_1$, which contradicts our choice of $u_1$.

If $\tau_{k+1}-\tau_k > \tau_1$ then 
\begin{equation*}
U(\tau_1+\tau_k) a = U(\tau_1) U(\tau_k)a = \lambda_1\lambda_k P_1u_k
\end{equation*}
and PST occurs from $a$ to $P_1u_k\neq P_{k+1}u_k (= u_{k+1})$ at time $(\tau_1+\tau_k)$.
Since $\tau_1+\tau_k < \tau_{k+1}$ is less than the minimum period of $a$, $P_1u_k \neq a$.
Further 
\begin{equation*}
   P_1u_k \not\in \{u_1, \ldots,u_k\} 
\end{equation*} 
because $P_1$ is a permutation matrix satisfying $P_1u_{j-1}=u_j$,
for $j=0,\ldots,k$.  The occurrence of PST from $a$
to  $P_1u_k \not \in \{u_0,\ldots, u_{k+1}\}$ contradicts our choice of $u_{k+1}$.

We conclude that $P_1=\cdots = P_m$, and when restricted to $\mathcal{S}_a$, this permutation is
the cycle $\left(u_0, u_1, \ldots, u_m\right)$.

(b) Let $P = U(\tau)$. We have seen previously that $P \in \mathcal{A}$ is a permutation matrix. Let $k$ be the multiplicative order of $P$. When restricted onto $\mathcal{S}_a$, we know from (a) that the permutation corresponding to $P$ is an $|\mathcal{S}_a|$-cycle. Hence, $P^{|\mathcal{S}_a|}$ has diagonal entries equal to $1$. Since $P \in \mathcal{A}$, we must have that $P^{|\mathcal{S}_a|} = I$. In other words, the multiplicative order of $P$ is equal to $|\mathcal{S}_a|$, for $a\in V(X)$. (c) follows immediately from the latter.

\label{cor:BMalgSize}
    Let $X$ be an oriented graph with adjacency matrix $A$ belongs to the Bose-Mesner algebra of some association scheme $\mathcal{A}$.
    If PST occurs from $a$ to another vertex in $X$ at time $\tau$ then $\vert \mathcal{S}_a\vert \in\{2,3,4,6\}$.
    {Moreover, $\tau \in \frac{\pi}{\sqrt{3}} \mathbb{Q}$ if $\vert \mathcal{S}_a\vert \in \{3,6\}$, and $\tau \in \pi \mathbb{Q}$ if $\vert \mathcal{S}_a\vert =4$.}

\label{thm:characterization}
PST occurs  from $e$ to $z$ at time $\tau$ in an oriented normal Cayley graph $\mathrm{Cay}(G, C)$ if and only if the following hold.
\begin{enumerate}
\item $z\in Z(G)$.
\item \label{Cond:chi}
For $\chi \in \mathrm{Irr}(G)$,
\[\dfrac{\chi(z)}{\chi(e)}=  \exp\left({\tau\ \dfrac{\chi(C)-\overline{\chi(C)}}{\chi(e)}}\right).\]
\end{enumerate}

By Theorem~\ref{thm:BMalgCyclicP}, if PST occurs from $e$ to $z$ then $z\in Z(G)$.
From \eqref{eq:idempdecomtmat}, $U(\tau)e = z$ if and only if
\begin{equation*}
  e^{\tau \theta_{\chi}} E_{\chi}e = E_{\chi} z, \quad \text{for $\chi \in \mathrm{Irr}(G)$} 
\end{equation*}
which is equivalent to
\begin{equation}\label{eq:chiCondition}
  e^{\tau \theta_{\chi}} \chi(g^{-1}) = \chi(zg^{-1}), \quad \text{for $\chi \in \mathrm{Irr}(G)$ and $g\in G$.}
\end{equation}
Since $z \in Z(G)$, $z$ acts on every irreducible module as a scalar matrix
and for $g\in G$
\begin{equation*}
    \dfrac{\chi(zg^{-1})}{\chi(g^{-1})} = \dfrac{\chi(z)}{\chi(e)}.
\end{equation*}
Condition~(\ref{Cond:chi}) follows immediately from \eqref{eq:chiCondition}.

\label{cor:non-exist}
 Let $G$ be a finite group and $z \in Z(G)$ be such that there exists a subset $Y\subset \mathrm{Irr}(G)$ satisfying:
 (i) $z \notin \mathrm{ker}(\chi)$, for all $\chi \in Y$; and (ii) $\bigcap\limits_{\chi \in Y} \mathbb{Q}(\chi)= \mathbb{Q}$. Then no normal Cayley graph on $G$ admits multiple state transfer on $\left\langle z \right\rangle$.

By Corollary~\ref{cor:multistate}, it suffices to show that there is no normal Cayley graph on $G$ admits PST from $e$ to $z$. We assume the contrary, that is, there is a normal Cayley graph $\mathrm{Cay}(G,C)$ that has PST from $e$ to $z$, at a time $\tau$.  Using Condition~(\ref{Cond:chi}) of Theorem~\ref{thm:characterization}, it follows that
\begin{subequations}
    \begin{align*}
        \dfrac{\chi(z)}{\chi(e)} &=e^{\tau \theta_{\chi}},
    \end{align*}
\end{subequations}
for all $\chi \in Y$.
Using (i) of the hypothesis, since $z\notin \mathrm{ker}(\chi)$, for all $\chi \in Y$, it follows from the above equation that $\theta_{\chi}\neq 0$ for all $\chi \in Y$.  By \cite[Theorem 7.1]{godsil2020perfect}, the vertex $e$ is periodic, and thus by \cite[Theorem~6.1]{godsil2020perfect}, it follows that for all $\chi,\psi \in Y$, we have, $\theta_{\chi}/\theta_{\psi} \in \mathbb{Q}$. Thus, since $\theta_{\psi}\in \mathbb{Q}(\psi)$,  we have $\theta_{\chi} \in \bigcap\limits_{\psi \in Y} \mathbb{Q}(\psi) =\mathbb{Q}$. Since $\theta_{\chi}$ is purely imaginary, it follows that $\theta_{\chi}=0$, which is a contradiction.

For $C \subset \mathbb{Z}_2^n \backslash \{\mathbf{0}\}$, let $\sigma$ be the sum of the elements in $C$.  Then 
\begin{equation*}
    U\left(\frac{\pi}{2}\right) \mathbf{0} = \sigma.
\end{equation*}
That is, PST occurs  in $\mathrm{Cay}(\mathbb{Z}_2^n, C)$ at time $\frac{\pi}{2}$ if and only if $\sigma \neq \mathbf{0}$.

Let $C \subset \mathbb{Z}_{3}^{n} \backslash \{\mathbf{0}\}$ be a connection set with $C \cap C^{-1}=\emptyset$ and $\sigma:=\sum\limits_{w \in C} w$. 
\begin{equation*}
    U\left(\frac{2\pi}{3\sqrt{3}}\right) \mathbf{0} = \sigma.
\end{equation*}
That is, PST occurs in $\mathrm{Cay}(\mathbb{Z}_3^n, C)$ from $\mathbf{0}$ to $\sigma$ at time $\frac{2\pi}{3\sqrt{3}}$ if and only if $\sigma \neq \mathbf{0}$. 
Moreover, if $\sigma \neq \mathbf{0}$, then $\mathrm{Cay}(\mathbb{Z}_3^n, C)$ has MST on $\langle \sigma\rangle$.

From \eqref{eq:theta_chi}, we have
\begin{align*}
\chi_{v}(C)-\overline{\chi_{v}(C)} =  \left( n_{v,1}-n_{v,2} \right) \sqrt{3} i,
\end{align*}
and
\begin{align*}
\chi_{v}(\sigma)  =\exp\left( \dfrac{2\pi i}{3} \sum\limits_{w \in C } v^{t}w \right) 
 = \exp\left( \dfrac{2\pi i \left( n_{v,1}+2n_{v,2} \right) } {3} \right). 
\end{align*}
The above two equalities imply that
\[\chi_{v}(\sigma) = \exp\left( \dfrac{2\pi}{3\sqrt{3}} \left(\chi_{v}(C)-\overline{\chi_{v}(C)}\right) \right),\] 
for all $v \in \mathbb{Z}_{3}^{n}$. Now, the result follows from Theorem~\ref{thm:characterization} and Corollary~\ref{cor:multistate}.

Let $C \subset \mathbb{Z}_{4}^{n} \backslash \{\mathbf{0}\}$ be a connection set with $C \cap C^{-1}=\emptyset$ and $\sigma:=\sum\limits_{w \in C} w$. \begin{equation*}
    U\left(\frac{\pi}{2}\right) \mathbf{0} = 2\sigma.
\end{equation*}
That is, PST occurs in $\mathrm{Cay}(\mathbb{Z}_4^n, C)$ from $\mathbf{0}$ to $2\sigma$ at time $\frac{\pi}{2}$ if and only if $\sigma$ has order 4.

We have
\begin{align*}
\chi_{v}(C)-\overline{\chi_{v}(C)} =  2i\left( n_{v,1}-n_{v,3} \right) ,
\end{align*}
and
\begin{align*}
\chi_{v}(2\sigma)  =\exp\left( \dfrac{4\pi i}{4} \sum\limits_{w \in C } v^{t}w \right) 
 = \exp\left( \pi i \left( n_{v,1}+3n_{v,3} \right)  \right). 
\end{align*}
The above two equalities imply that
\[\chi_{v}(2\sigma) = \exp\left( \dfrac{\pi}{2} \left(\chi_{v}(C)-\overline{\chi_{v}(C)}\right) \right),\] 
for all $v \in \mathbb{Z}_{4}^{n}$. Now, the result follows from Theorem~\ref{thm:characterization}.

Using Corollary~\ref{cor:multistate}, it suffices to show that PST occurs from $e$ to $x^{2^{n-3}}$, at time $\tau =\pi/4$. In other words, using Theorem~\ref{thm:characterization}, it suffices to show that
\begin{equation}\label{eq:mmcchar}
\exp\left(\dfrac{\theta_{\phi}\pi}{4} \right) = \dfrac{\phi(x^{2^{n-3}})}{\phi(1)},
\end{equation}
for all $\phi \in \mathrm{Irr}(M_{2}(n))$.

We first show that the  above is true for linear characters. As we mentioned at the start of this section, we have  $[M_{2}(n),\ M_{2}(n)] =\langle x^{2^{n-2}}\rangle$, and thus given a linear character $\chi$ of $M_{2}(n)$, we have $\chi^{2^{n-2}}=1$. By $o(\chi)$, we denote the order of $\chi$, as an element of the dual group $\widehat{M_{2}(n)}$.  

\paragraph{Case 1:} Assume that $o(\chi)=2^{r}$, for some $r\geq 3$. Then, we have $\chi(x^{2^{r-1}})=-1$ and thus $\chi(x^{4(k+2^{r-3})+1})=-\chi(x^{4k+1})$, for all $0\leq k \leq 2^{n-3}-1$. We note that the map $x^{4k+1} \mapsto x^{4(k+2^{r-3})+1}$ is a bijection on $\{x^{4k+1}\ :\ 0\leq k \leq 2^{n-3}-1 \}$. Therefore, we have 
 \begin{align*}
  \sum\limits_{k=0}^{2^{n-3}-1} \chi(x^{4k+1}) & = \sum\limits_{k=0}^{2^{n-3}-1} \chi(x^{4(k+2^{r-3})+1})\\
  & = -\sum\limits_{k=0}^{2^{n-3}-1} \chi(x^{4k+1}),
 \end{align*}
 with the last equality following from the fact that $\chi(x^{4(k+2^{r-3})+1})=-\chi(x^{4k+1})$, for all $k$. Thus, $\sum\limits_{k=0}^{2^{n-3}-1} \chi(x^{4k+1})=0$.
 We now have
\begin{align*}
\theta_{\chi} &= \chi(x^{2^{n-3}}) + 2\chi(x^{2^{n-4}} \sigma) + \sum\limits_{k=0}^{2^{n-3}-1} \chi(x^{4k+1})- \overline{\left(\chi(x^{2^{n-3}}) + 2\chi(x^{2^{n-4}} \sigma) + \sum\limits_{k=0}^{2^{n-3}-1} \chi(x^{4k+1}) \right)} \\
& = \chi(x^{2^{n-3}}) + 2\chi(x^{2^{n-4}} \sigma) -\overline{ \left( \chi(x^{2^{n-3}}) + 2\chi(x^{2^{n-4}} \sigma) \right) }.
\end{align*}
Since $x^{2^{n-2}} \in [M_{2}(n), M_{2}(n)] \leq \mathrm{ker}(\chi)$, we have  $\chi(x^{2^{n-2}})=1$, we have  $\chi(x^{2^{n-3}})=\pm 1$, and $\chi(x^{2^{n-4}} \sigma)= \chi(\sigma) \chi(x^{2^{n-4}})=\pm\chi(\sigma)\sqrt{\chi(x^{2^{n-3}})}$. Since $\sigma$ is an element of order $2$, it follows that $\chi(\sigma)=\pm 1$, and thus $\chi(x^{2^{n-4}} \sigma)= \pm \sqrt{\chi(x^{2^{n-3}})}$. Therefore, we have
\begin{align*}
 \theta_{\chi} = \begin{cases}
 0 & \text{if $\chi(x^{2^{n-3}})=1$} \\
  \pm 4 i & \text{if $\chi(x^{2^{n-3}})=-1$,}
 \end{cases}
\end{align*}
and thus \eqref{eq:mmcchar} is satisfied by all linear characters of order at least $8$.

\paragraph{Case 2:} Assume that $o(\chi) =4$. In this case, have $\chi(x)=\pm i$, and thus, 
\begin{align}\label{eq:order4}
     \sum\limits_{k=0}^{2^{n-3}-1} \chi(x^{4k+1})= \pm 2^{n-3} i, \text{when $o(\chi)=4$}. 
 \end{align}
We also have $\chi(x^{2^{n-3}}), \chi(x^{2^{n-4}} \sigma) \in \mathbb{Q}$. Therefore, we have $\theta_{\chi}= \pm 2^{n-2} i$. As $n\geq 5$, we observe that (a) $\chi(x^{2^{n-3}})=1$ and (b) $(\pi/4)\theta_{\chi}$ must be an even multiple of $\pi$. Therefore \eqref{eq:mmcchar} is satisfied for all linear characters of order $4$.

\paragraph{Case 3:} We now consider the case $o(\chi) =2$. In this case, must have $\chi(x)=\pm 1$ and $\chi(\sigma)=\pm1$. Therefore, $\chi(g) \in \mathbb{Q}$, and thus, $\theta_{\chi}=0$. Since $\chi(x)=\pm 1$, we have $\chi(x^{2^{n-3}})=1$, and thus \eqref{eq:mmcchar} holds for linear characters of order $2$ as well.

We now move on to non-linear irreducible characters. Using Lemma~\ref{lem:nonlin}, it follows that for a non-linear irreducible $\chi$, we have $\chi(x^{2^{n-3}})/\chi(1)= \pm i$ and thus $\theta_{\chi}= 2\chi(x^{2^{n-3}})/\chi(1)= \pm 2i$, with the same sign.  It follows that \eqref{eq:mmcchar} holds for all non-linear irreducible characters as well.

\label{lem:centralcharacterc1}
Consider $f:[n]\to \mathrm{Irr}(G)$ and a partition-valued function $\Lambda$ on $\mathrm{Irr}(G)$ satisfying $|\Lambda(\phi)|=|f^{-1}(\phi)|$, for all $\phi \in \mathrm{Irr}(G)$. Then, we have
\begin{equation*}
\dfrac{\psi_{f,\Lambda}(((x,e,\ldots, e); (1)))-\overline{\psi_{f,\Lambda}(((x,e,\ldots, e); (1)))}}{\psi_{f,\Lambda}(1)} = \sum\limits_{\mu \in \mathrm{Irr}(G)}  \dfrac{|f^{-1}(\mu)| (\mu(x)-\overline{\mu(x)})}{n\mu(1)}.
\end{equation*}

We recall that the set $\{\chi_{f\circ \pi}\ :\ \pi \in S_{n}\}$ is the set of conjugates of $\chi_{f}$.
 Using Clifford theory(\cite[Theorems 6.2 and 6.11]{isaacs1994character}), we have
 \begin{equation}\label{eq:wreathrestriction}
\mathrm{Res}^{G \wr S_{n}}_{G^{n}} \psi_{f,\Lambda} = \prod\limits_{\phi \in f\left([n]\right)} \rho_{f, \phi}(1) \times \left[\sum\limits_{h\in\{f\circ \pi\ :\ \pi \in S_{n}\}} \chi_{h}\right].
 \end{equation}
By a conjugate of $f$, we mean an element of the set $\{f\circ \pi\ :\ \pi \in S_{n}\}$. Given $i\in [n]$ and $\mu \in \mathrm{Irr}(G)$, let $\Vert f \Vert_{\mu}$ denote the number of conjugates $h$ of $f$, with $h(1)=\mu$. Elementary counting arguments yield that 
\[\Vert f \Vert_{\mu} =  \dfrac{(n-1)!}{\left(|f^{-1}(\mu)|-1\right)! \prod\limits_{\phi \in \mathrm{Irr}(G) \setminus \{\mu\}} |f^{-1}(\phi)|! } \]

Using \eqref{eq:wreathrestriction}, we have 
\begin{align*}
\psi_{f,\Lambda}(((x,e,\ldots, e); (1))) & = \prod\limits_{\phi \in \mathrm{Irr}(G)} \rho_{\Lambda(\phi)}(1) \times \left[\sum\limits_{\mu \in \mathrm{Irr}(G)} \Vert f\Vert_{\mu} \mu (x)  \prod\limits_{\nu \in \mathrm{Irr}(G) \setminus \{\mu\}} \nu(1). \right ]
\end{align*}

The result follows by noting that \[\psi_{f,\Lambda}(1) = \left(\prod\limits_{\phi \in \mathrm{Irr}(G)} \rho_{\phi, f}(1)\phi(1)\right) \times \Vert f \Vert_ {\mu} \times n\times |f^{-1}(\mu)|^{-1}.\]

\label{thm:wreath}
Let $n\geq 2$ be a natural number and let $X:=\mathrm{Cay}(G,C)$ be an oriented normal Cayley graph that admits PST from $e$ to $z\in Z(G)$, at a time $\tau$. 
Let 
\begin{subequations}\label{eq:wreathconnex}
\begin{align}
\tilde{C}_{1} &=  \bigcup\limits_{i \in [n]} \left\{((x_{1}, \ldots x_{n}); (1))\ :\ x_{i}\in C\ \& \ x_{j}=e,\ \forall j\neq i\right\}\\
\tilde{C}_{2} &= \left\{(\mathbf{x};\pi)\ :\ \text{$\pi$ is an $n$-cycle}\ \&\ \mathbf{x}_{\pi}\in C\right\}.
\end{align} 
\end{subequations}
Then $X \wr n := \mathrm{Cay}(G\wr S_{n},\ \tilde{C}_{1}\cup \tilde{C}_{2})$ admits PST at time $\tau$ from $(e,e,\ldots, e)$ to $(z,z,\ldots, z)$.

By Theorem~\ref{thm:characterization}, it suffices to show that 
\[\dfrac{\overline{\psi(z,\ldots, z ) }}{\psi(1)} = \exp\left(\tau \theta_{\psi}\right),\] for all $\psi \in \mathrm{Irr}(G \wr S_{n})$. Here,
 \begin{equation}\label{eq:tpsiwr}
\theta_{\psi} = \dfrac{\psi(\tilde{C}_{1})+\psi(\tilde{C}_{2})-\overline{\psi(\tilde{C}_{1})-\psi(\tilde{C}_{2})}}{\psi(1)}.
\end{equation}

Consider some $\psi \in \mathrm{Irr}(G \wr S_{n})$.
Following the description of $\mathrm{Irr}(G \wr S_{n})$ given at the start of this section, given $\psi \in \mathrm{Irr}(G\wr S_{n})$, there exists $f:[n] \to \mathrm{Irr}{G}$ and a partition-valued function $\Lambda$ on $\mathrm{Irr}(G)$ with $|\Lambda(\phi)|=|f^{-1}(\phi)|$ (for all $\phi \in \mathrm{Irr}(G)$) such that $\psi=\psi_{f,\Lambda}$ (as defined in \eqref{eq:charwreathproduct}). We first compute $\theta_{\psi_{f,\Lambda}}$.

\paragraph{Case 1:} Assume that $|f([n])|>1$. Using Lemma~\ref{lem:centralcharacterc2}, it follows that
\[\theta_{\psi_{f, \Lambda}} = \dfrac{\psi_{f, \Lambda}(\tilde{C}_{1}))-\overline{\psi_{f, \Lambda}(\tilde{C}_{1})}}{\psi_{f, \Lambda}(1)}.\] We note that every element of $\tilde{C}_{1}$ is conjugate to an element of the form $((x,e,\ldots ,e) ; (1))$ for some $x\in C$, and that the number of $S_{n}$-conjugates in $\tilde{C}_{1}$ of the element $((x,e,\ldots ,e) ; (1))$ (with $x \in C$) is $n$ . It now follows from Lemma~\ref{lem:centralcharacterc1} that 
\begin{align*}
\dfrac{\psi_{f, \Lambda}(\tilde{C}_{1})}{\psi_{f, \Lambda}(1)} = n\sum\limits_{\phi \in \mathrm{Irr}(G)}  \dfrac{|f^{-1}(\phi)|\phi(C)}{n\phi(1)},
\end{align*}
and therefore, if $\theta_{\phi}$ is the eigenvalue associated with $\phi$, of $\mathrm{Cay}(G,C)$, we have
\begin{equation}\label{eq:c1sum}
\theta_{\psi_{f, \Lambda}} = \sum\limits_{\phi \in \mathrm{Irr}(G)} |f^{-1}(\phi)| \theta_{\phi},\ \text{provided $|f([n]|>1$.}
\end{equation}

 \paragraph{Case 2:} Now, we assume that $f([n])=\{\phi\}$. Set $\lambda:=\Lambda(\phi)$. Fix an $n$-cycle, $\sigma \in S_{n}$. We note that every element in $\tilde{C}_{2}$ is conjugate to an element of the form $(\mathbf{x}; \sigma)$ with $\mathbf{x}_{\sigma} \in C$. We count that for each $c \in C$, that $X_{c}:=\{(\mathbf{x}; \sigma) \ : \mathbf{x}_{\sigma} = c \}$ is a set of size $|G|^{n-1}$.  Since every element of $X_{c}$ lies in the same conjugacy class, using Lemma~\ref{lem:centralcharacterc2}, we have
 \begin{align}\label{eq:formulac2}
     \sum\limits_{g \in X_{c}}\dfrac{\psi_{f,\Lambda}(g)-\overline{\psi_{f,\Lambda}(g)}}{\psi_{f, \Lambda}(1)} & =k_{f, \lambda} |Z(G)|^{n-1} \dfrac{\phi(c)-\overline{\phi(c)}}{\phi(1)\times (n-1)!},
 \end{align}
 for some $k_{f,\Lambda}\in \mathbb{Z}$.
 We recall that there are exactly $(n-1)!$ number of $n$-cycles in $S_{n}$. Thus, we have
\begin{align*}
\dfrac{\psi_{f, \Lambda}(\tilde{C}_{2})-\overline{\psi_{f, \Lambda}(\tilde{C}_{2})}}{\psi_{f, \Lambda}(1)} &= (n-1)!\sum\limits_{c \in C}\sum\limits_{g \in X_{c}}\dfrac{\psi_{f,\Lambda}(g)-\overline{\psi_{f,\Lambda}(g)}}{\psi_{f, \Lambda}(1)} \\
&= \sum\limits_{c \in C}k_{f,\Lambda}|Z(G)|^{n-1} \dfrac{\phi(c) - \overline{\phi(c)}}{\phi(1)} \ \text{(using \eqref{eq:formulac2})}\\
&=k_{f,\Lambda}|Z(G)|^{n-1}\theta_{\phi}.
\end{align*}
Arguing as in Case 1, using Lemma~\ref{lem:centralcharacterc1}, we have
\[\dfrac{\psi_{f, \Lambda}(\tilde{C}_{1})-\overline{\psi_{f, \Lambda}(\tilde{C}_{1})}}{\psi_{f, \Lambda}(1)}=n\theta_{\phi},\] and therefore, we have 

\begin{equation}\label{eq:c2sum}
\theta_{\psi_{f, \Lambda}} = n \theta_{\phi} + k_{f,\Lambda}|Z(G)|^{n-1}\theta_{\phi},\ \text{, for some $k_{f,\Lambda}\in \mathbb{Z}$, provided $f([n])=\{\phi\}$.}
\end{equation}

Using, \eqref{eq:tpsiwr}, \eqref{eq:c1sum} and \eqref{eq:c2sum}, we have 
\begin{align}\label{eq:taupsi}
\exp\left( \tau \theta_{\psi_{f,\Lambda}}\right) &= \begin{cases} \prod\limits_{\phi \in \mathrm{Irr}(G)} \left[ \exp\left( \tau \theta_{\phi} \right) \right]^{|f^{-1}(\phi)|} & \text{if $|f([n])|>1$,}\\
\exp{(\tau\theta_{\phi})}^{n} \times \exp(\tau \theta_{\phi})^{k_{\psi} |Z(G)|^{n-1}} &\text{if $f([n])=\{\phi\}$.} 
\end{cases}
\end{align}
Since $\mathrm{Cay}(G, C)$ admits PST from $e$ to $z$ at time $\tau$, by Theorem~\ref{thm:characterization}, we have \[\exp\left( \tau \theta_{\phi} \right) = \frac{\overline{\phi(z)}}{\phi(1)},\] for all $\phi \in \mathrm{Irr}(G)$. Applying the above in \eqref{eq:taupsi}, yields

\begin{align*}
\exp\left( \tau \theta_{\psi_{f,\Lambda}}\right) & = \begin{cases}
\prod\limits_{\phi \in \mathrm{Irr}(G)} \left( \frac{\overline{\phi(z)}}{\phi(1)} \right)^{|f^{-1}(\phi)|}  & \text{if $|f([n])|>1$,} \\
\left( \dfrac{\overline{\phi(z)}}{\phi(1)} \right)^{n} \times \left(\dfrac{\overline{\phi(z)}}{\phi(1)}\right)^{k_{f,\Lambda}|Z(G)|^{n-1}} & \text{if $f([n])=\{\phi\}$.}
\end{cases}
\end{align*} 
Since $z \in Z(G)$ and since $\dfrac{\overline{\phi(z)}}{\phi(1)}$ is a $|z|$-th root of unity, it follows that $\dfrac{\overline{\phi(z)}}{\phi(1)}^{|Z(G)|}=1$. Therefore, we have
\begin{align*}
\exp\left( \tau \theta_{\psi_{f,\Lambda}}\right) & = \prod\limits_{\phi \in \mathrm{Irr}(G)} \left( \dfrac{\overline{\phi(z)}}{\phi(1)} \right)^{|f^{-1}(\phi)|} \\
&= \dfrac{\overline{\psi_{f,\Lambda}(z,\ldots, z)} }{\psi_{f,\Lambda}(1)}.
\end{align*} 
The result now follows from Theorem~\ref{thm:characterization}.

\label{thm:wreathundirected}
Let $n\geq 2$ be a natural number and let $X:=\mathrm{Cay}(G,C)$ be a normal Cayley graph that admits PST from $e$ to $z\in Z(G)$, at a time $\tau$. 
Let 
\begin{subequations}
\begin{align*}
\tilde{C}_{1} &=  \bigcup\limits_{i \in [n]} \left\{((x_{1}, \ldots x_{n}); (1))\ :\ x_{i}\in C\ \& \ x_{j}=e,\ \forall j\neq i\right\}\\
\tilde{C}_{2} &= \left\{(\mathbf{x};\pi)\ :\ \text{$\pi$ is an $n$-cycle}\ \&\ \mathbf{x}_{\pi}\in C\right\}.
\end{align*} 
\end{subequations}
Then $X \wr n := \mathrm{Cay}(G\wr S_{n},\ \tilde{C}_{1}\cup \tilde{C}_{2})$ admits PST at time $\tau$ from $(e,e,\ldots, e)$ to $(z,z,\ldots, z)$.
